WITH new_user AS (
  INSERT INTO users (email, password_hash, consent_given_at, consent_version)
  VALUES ($1::text, crypt($2::text, gen_salt('bf', 12)), now(), 'v2')
  ON CONFLICT (email) DO NOTHING
  RETURNING id
), prefs AS (
  INSERT INTO preferences (user_id) SELECT id FROM new_user
), log_ok AS (
  INSERT INTO audit_log (event, user_id, details)
  SELECT 'register_ok', id, '{}'::jsonb FROM new_user
), log_dup AS (
  INSERT INTO audit_log (event, user_id, details)
  SELECT 'register_duplicate', (SELECT id FROM users WHERE email = $1::text), '{}'::jsonb
  WHERE NOT EXISTS (SELECT 1 FROM new_user)
)
SELECT 'done' AS status;

