new_user AS (
  INSERT INTO users (email, password_hash, consent_given_at, consent_version)
  SELECT $1::text, crypt($2::text, gen_salt('bf', 12)), now(), 'v2' FROM ok
  ON CONFLICT (email) DO NOTHING
  RETURNING id
), prefs AS (
  INSERT INTO preferences (user_id) SELECT id FROM new_user
), log_ok AS (
  INSERT INTO audit_log (event, user_id, details) SELECT 'register_ok', id, '{}'::jsonb FROM new_user
), log_dup AS (
  INSERT INTO audit_log (event, user_id, details)
  SELECT 'register_duplicate', (SELECT id FROM users WHERE email = $1::text), '{}'::jsonb
  WHERE EXISTS (SELECT 1 FROM ok) AND NOT EXISTS (SELECT 1 FROM new_user)
), done AS (
  DELETE FROM auth_pending WHERE chat_session_id = $4::text AND EXISTS (SELECT 1 FROM ok)
)
SELECT 'done' AS status;

