const text = $('Analyser le message').first().json.message;
const t = text.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');

const PATTERNS = [
  ['ignorer-consignes', /(ignore|oublie|desobeis|contourne|disregard|forget|override).{0,40}(instruction|consigne|regle|rule|prompt|directive|guideline)/],
  ['reveler-prompt', /(system|developer|systeme) ?(prompt|message|instruction)|prompt (systeme|initial)|(reveal|show|print|montre|affiche|donne|repete).{0,30}(prompt|instructions)/],
  ['changer-de-role', /(you are now|tu es maintenant|desormais tu|from now on|a partir de maintenant tu|act as|joue le role|pretend (to be|you))/],
  ['jailbreak', /(jailbreak|\bdan\b mode|developer mode|mode developpeur|do anything now)/],
  ['elevation-privileges', /(devenir|passe(r)?|me donner|donne.moi|give me|make me|set my).{0,30}(admin|administrateur|root|superuser)|\bsudo\b|role ?= ?.?admin/],
  ['autres-utilisateurs', /(autres?|tous les|toutes les|all|every|other|someone else.?s|d.un autre) (utilisateurs?|users?|comptes?|accounts?|clients?)/],
  ['champs-internes', /user_id|password_hash|unsubscribe_token|chat_session_id|audit_log|information_schema|pg_catalog|pg_shadow/],
  ['injection-sql', /(drop|truncate|alter) +(table|database|schema)|union +select|delete +from|insert +into|'\s*or\s*'?\d'?\s*=\s*'?\d|;\s*--/],
  ['delimiteurs-llm', /<\|[a-z_]+\|>|\[\/?inst\]|<<\/?sys>>|^\s*(system|assistant)\s*:/m],
];

const matches = PATTERNS.filter(([, re]) => re.test(t)).map(([label]) => label);
return [{ json: { blocked: matches.length > 0, matches, length: text.length } }];

const item = $input.first().json;
let text = typeof item.output === 'string' ? item.output : '';
if (!text) text = "Désolé, je n'ai pas pu traiter votre demande. Réessayez dans un instant.";
// au cas où l'IA renverrait un hash ou un uuid
text = text
  .replace(/\$2[aby]\$\d{2}\$[./A-Za-z0-9]{53}/g, '[masqué]')
  .replace(/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/gi, '[masqué]');
return [{ json: { output: text.slice(0, 3000) } }];

// Ce message va-t-il coûter un appel à l'IA ? Si oui, il passe d'abord par la limite.
// - « chat » (utilisateur connecté) : l'agent sera appelé, toujours.
// - « anonymous » : l'agent ne sera jamais appelé, mais on peut demander à l'IA de comprendre la phrase.
// On n'interprète que les phrases courtes : une vraie demande (« je veux m'inscrire ») tient en peu de mots.
// Pendant l'inscription ou la connexion guidée (action = étape), rien ne part vers l'IA :
// le mot de passe ne doit jamais lui arriver.
const etape = $input.first().json;
const message = $('Analyser le message').first().json.message || '';
const court = message.length > 0 && message.length <= 200;
const interpreter = (etape.action === 'chat' || etape.action === 'anonymous') && court;
const limiter = etape.action === 'chat' || interpreter;
return [{ json: { ...etape, interpreter, limiter } }];

// Limites de messages qui passent par l'IA (une ligne dans chat_ai_requests par message).
// 1 message peut coûter jusqu'à 2 appels Gemini (comprendre la phrase, puis l'agent) :
// on garde donc une marge sous le quota du jour.
const LIMITES = {
  parMinute: 6,            // une session
  parJourSession: 100,     // une session
  parJourCompte: 200,      // un compte, toutes ses sessions
  parJourAnonymes: 150,    // toutes les sessions non connectées ensemble
  parJourTotal: 600,       // tout le monde
};

const c = $input.first().json;
const n = (valeur) => Number(valeur) || 0;
const connecte = !!$('Faut-il limiter ?').first().json.user_id;

// Les anonymes ont une petite part du total : quelqu'un qui change d'identifiant de session
// ne peut pas épuiser le quota des utilisateurs connectés.
let raison = '';
if (n(c.session_minute) >= LIMITES.parMinute) raison = 'trop_vite';
else if (n(c.session_jour) >= LIMITES.parJourSession) raison = 'limite_session';
else if (connecte && n(c.user_jour) >= LIMITES.parJourCompte) raison = 'limite_compte';
else if (!connecte && n(c.anonymes_jour) >= LIMITES.parJourAnonymes) raison = 'limite_anonymes';
else if (n(c.total_jour) >= LIMITES.parJourTotal) raison = 'limite_totale';

const MESSAGES = {
  trop_vite: 'Vous écrivez très vite : attendez quelques secondes puis réessayez.',
  limite_session: "Vous avez atteint la limite de messages pour aujourd'hui. Revenez demain.",
  limite_compte: "Vous avez atteint la limite de messages pour aujourd'hui. Revenez demain.",
  limite_anonymes: 'Le service reçoit beaucoup de demandes en ce moment. Réessayez un peu plus tard.',
  limite_totale: 'Le service reçoit beaucoup de demandes en ce moment. Réessayez un peu plus tard.',
};
return [{ json: { autorise: raison === '', raison, message: MESSAGES[raison] || '' } }];

// L'IA ne fait que classer la phrase dans une liste fermée. C'est ce code qui décide si l'action est permise.
const etape = $('Faut-il limiter ?').first().json;
const connecte = !!etape.user_id;
const reponse = $input.first().json;
const intention = typeof reponse.intention === 'string' ? reponse.intention : 'aucune';

// intention -> action qui existe déjà dans le workflow, et qui a le droit de la demander
// (connecte : true = utilisateur connecté seulement, false = non connecté seulement, null = tout le monde)
const ACTIONS = {
  inscription: { action: 'register_start', connecte: false },
  connexion: { action: 'login_start', connecte: false },
  annuler: { action: 'cancel', connecte: false },
  confidentialite: { action: 'privacy', connecte: null },
  aide: { action: 'help', connecte: null },
  deconnexion: { action: 'logout', connecte: true },
  mes_donnees: { action: 'export', connecte: true },
  // seulement la demande : le compte n'est supprimé que si l'utilisateur tape exactement « confirmer suppression »
  supprimer_compte: { action: 'delete_request', connecte: true },
};

let action = etape.action;
if (Object.hasOwn(ACTIONS, intention)) {
  const voulue = ACTIONS[intention];
  if (voulue.connecte === null || voulue.connecte === connecte) action = voulue.action;
}
return [{ json: { action, user_id: etape.user_id, pending_email: etape.pending_email } }];

// Ce message n'est pas interprété par l'IA : l'action reste celle décidée avant la limite.
const etape = $('Faut-il limiter ?').first().json;
return [{ json: { action: etape.action, user_id: etape.user_id, pending_email: etape.pending_email } }];

